    filters,
    ...length(),
    active_during = active_during,
    collect = collect,
    limit = limit,
    call = call
  )
  tbl <- db_tbl("presiding_officers")
  tbl <- filter_args(tbl, filters, call = call)
  tbl <- filter_active_during(tbl, active_during, "DateStart", "DateEnd", call = call)
  tbl <- select_columns(tbl, columns, call = call)
  collect_result(tbl, collect = collect, limit = limit, call = call)
}

